ROOT = Path(__file__).resolve().parents[1]
PACK = ROOT / 'data' / 'case'
ACTOR = 'Analista de teste'


class WorkflowSafety(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory(prefix='tarvo-quality-')
        self.db_path = Path(self.tmp.name) / 'test.sqlite3'
        self.store = Store(self.db_path, PACK)

    def tearDown(self):
        self.store.close_db()
        self.tmp.cleanup()

    def act(self, endpoint, **fields):
        return self.store.mutate(endpoint, {'actor': ACTOR, **fields})

    def issue(self):
        return self.store.state()['results']['pendencias'][0]

    def draft(self, kind='billing'):
        if kind == 'billing':
            invoice = self.store.state()['results']['notas'][0]
            payload = {'invoice_id': invoice['id_saida']}
        elif kind == 'dispute':
            payload = {'issue_id': self.issue()['id_saida']}
        else:
            payload = {'report': True}
        email = self.act('emails/draft', **payload)['email']
        return self.act('emails/save', id=email['id'], [EMAIL_REMOVIDO]',
                        subject=email['subject'], body=email['body'])['email']

    def contact(self, **changes):
        payload = {'name': 'Teste interno', 'email': [EMAIL_REMOVIDO]', 'kind': 'internal',
                   'cnpj': '', 'min_severity': 'bloqueante', 'frequency': 'digest', 'enabled': True}
        payload.update(changes)
        self.act('contacts', **payload)

    def test_actor_is_required_for_every_change(self):
        for action in ('recalculate', 'close', 'decisions', 'rates', 'merchants', 'parameters',
                       'contacts', 'import', 'emails/draft', 'emails/approve', 'emails/send'):
            with self.subTest(action=action):
                with self.assertRaises(ValueError):
                    self.store.mutate(action, {})

    def test_pending_issues_block_closing_without_explicit_waiver_and_reason(self):
        self.assertGreater(self.store.state()['summary']['open_issues'], 0)
        for fields in ({}, {'allow_open': True}, {'allow_open': 'true', 'reason': 'revisado'}):
            with self.subTest(fields=fields):
                with self.assertRaises(ValueError):
                    self.act('close', **fields)
        self.assertEqual(self.store.state()['closing']['status'], 'open')
        self.act('close', allow_open=True, reason='Demo: aceite explícito de todas as ressalvas')
        closing = self.store.state()['closing']
        self.assertEqual(closing['status'], 'closed')
        self.assertTrue(closing['waiver'])
        self.assertEqual(closing['actor'], ACTOR)
        self.assertTrue(closing['open_issue_ids'])

    def test_reject_keeps_issue_open_and_decision_has_actor_time_and_reason(self):
        issue = self.issue()
        before = self.store.state()['summary']['open_issues']
        self.act('decisions', id=issue['id_saida'], action='reject', note='Regra contestada pelo analista')
        state = self.store.state()
        row = next(p for p in state['results']['pendencias'] if p['id_saida'] == issue['id_saida'])
        self.assertEqual(row['status'], 'rejected')
        self.assertEqual(state['summary']['open_issues'], before)
        self.assertEqual(row['decision']['actor'], ACTOR)
        self.assertEqual(row['decision']['note'], 'Regra contestada pelo analista')
        self.assertTrue(row['decision']['at'])

    def test_confirmed_decision_survives_reopen_database_and_identical_recalculation(self):
        issue = self.issue()
        self.act('decisions', id=issue['id_saida'], action='confirm', note='Encaminhado para financeiro')
        self.store.close_db()
        self.store = Store(self.db_path, PACK)
        self.act('recalculate', period='2026-09')
        saved = next(p for p in self.store.state()['results']['pendencias'] if p['id_saida'] == issue['id_saida'])
        self.assertEqual(saved['status'], 'resolved')
        self.assertEqual(saved['decision']['actor'], ACTOR)

    def test_changed_raw_evidence_invalidates_decision_with_same_id_type_and_value(self):
        issue = next(p for p in self.store.state()['results']['pendencias']
                     if p['tipo'] == 'DIVERGENCIA_TAXA' and p['ref_origem'].startswith('TX'))
        self.act('decisions', id=issue['id_saida'], action='confirm', note='Confirmada a evidência original')
        accepted = next(p for p in self.store.state()['results']['pendencias'] if p['id_saida'] == issue['id_saida'])
        self.assertEqual(accepted['status'], 'resolved')
        copied = Path(self.tmp.name) / 'reimported'
        copied.mkdir()
        for source in PACK.iterdir():
            if source.is_file() and source.name[:2] in ('01', '02', '03', '04', '05'):
                shutil.copy2(source, copied / source.name)
        checkout_file = copied / '01_orbe_relatorio_comissoes_set2026.csv'
        with checkout_file.open(newline='', encoding='utf-8-sig') as source:
            reader = csv.DictReader(source, delimiter=';')
            fields = reader.fieldnames
            rows = list(reader)
        changed = next(r for r in rows if r['id_transacao'] == issue['ref_origem'])
        changed['nome_estabelecimento'] += ' (EVIDÊNCIA REVISADA)'
        with checkout_file.open('w', newline='', encoding='utf-8') as output:
            writer = csv.DictWriter(output, fields, delimiter=';')
            writer.writeheader()
            writer.writerows(rows)
        self.act('import', source_dir=str(copied), period='2026-09')
        reopened = next(p for p in self.store.state()['results']['pendencias'] if p['id_saida'] == issue['id_saida'])
        self.assertEqual(reopened['tipo'], issue['tipo'])
        self.assertEqual(reopened['valor_brl'], issue['valor_brl'])
        self.assertNotEqual(reopened['source_fingerprint'], issue['source_fingerprint'])
        self.assertEqual(reopened['status'], 'open')
        self.assertIsNone(reopened['decision'])

    def test_trace_details_are_scoped_to_output_and_include_original_input(self):
        state = self.store.state()
        commission = next(c for c in state['results']['comissoes'] if c['linha_negocio'] == 'CHECKOUT')
        ident = commission['id_saida']
        trace = self.store.trace(ident)
        self.assertTrue(trace['rows'])
        self.assertTrue(trace['details'])
        self.assertTrue(all(r['id_saida'] == ident for r in trace['rows']))
        self.assertTrue(all(d['id_saida'] == ident for d in trace['details']))
        self.assertEqual(len(trace['rows']), len(trace['details']))
        for detail in trace['details']:
            original = detail['entrada']
            self.assertEqual(original['id'], detail['ref_origem'])
            self.assertTrue({'gross', 'applied_rate_pct', 'reported_fee', 'net', 'date', 'type'}.issubset(original))
            self.assertTrue(detail['formula'])
            self.assertTrue(detail['regra'])
        # The same transaction also contributes to invoices/issues; those details must stay out.
        refs = {r['ref_origem'] for r in trace['rows']}
        self.assertTrue(any(d['ref_origem'] in refs and d['id_saida'] != ident
                            for d in state['results']['details']))
        self.assertEqual(self.store.trace('ID-INEXISTENTE'), {'rows': [], 'details': []})

    def test_recalculation_reopens_a_closed_month(self):
        self.act('close', allow_open=True, reason='Exceções aceitas para teste')
        self.act('recalculate', period='2026-09')
        self.assertEqual(self.store.state()['closing']['status'], 'open')

    def test_new_overlapping_rate_is_rejected_without_partial_mutation(self):
        before = self.store.state()['rates']
        existing = next(r for r in before if r['start'] and not r.get('end'))
        with self.assertRaises(ValueError):
        self.assertFalse(any("RESSALVA" in e["tipo"] for e in self.ctx["exceptions"]))

    def test_export_requires_approval_and_can_resume_without_scratch(self):
        with tempfile.TemporaryDirectory() as tmp:
            ctx = copy.deepcopy(self.ctx)
            with self.assertRaises(PermissionError): export_artifacts(ctx, [], tmp)
            ctx.update(approved=True, scratch={})
            result = export_artifacts(ctx, [], tmp)
            self.assertEqual(result["debit_total"], result["credit_total"])
            self.assertTrue((Path(tmp) / "lancamentos_fenix.csv").exists())

    def test_two_distinct_run_paths_produce_identical_parquet_and_csv_bytes(self):
        with tempfile.TemporaryDirectory() as tmp:
            other, hashes = run_until_gate(tmp)
            self.assertEqual(self.hashes, hashes)
            original = copy.deepcopy(self.ctx)
            original["approved"] = other["approved"] = True
            one = export_artifacts(original, [], Path(tmp) / "one")
            two = export_artifacts(other, [], Path(tmp) / "two")
            self.assertEqual(one, two)
            self.assertTrue(all(not str(s.get("path", "")).startswith("/") for s in other["datasets"]["sources"]))

    def test_adjustment_is_applied_to_both_sides_without_mutating_raw(self):
        with tempfile.TemporaryDirectory() as tmp:
            ctx = copy.deepcopy(self.ctx)
            ctx["approved"] = True
            exception = next(e for e in ctx["exceptions"] if e["tipo"] == "CREDITO_NAO_IDENTIFICADO")
            before = copy.deepcopy(ctx["datasets"]["lancamentos"])
            adjustment = {"exception_id": exception["id"], "acao": "ajustar", "valor": "7000.00", "conta": "1.1.09.002", "justificativa": "Valor confirmado em documento revisado", "actor": "Analista"}
            result = export_artifacts(ctx, [adjustment], tmp)
            self.assertEqual(result["adjustments_applied"], 1)
            self.assertEqual(result["debit_total"], result["credit_total"])
            self.assertEqual(ctx["datasets"]["lancamentos"], before)
            content = (Path(tmp) / "lancamentos_fenix.csv").read_text()
            self.assertIn("7000.00", content)

    def test_atlas_cannot_create_revenue_by_adjustment_but_can_be_excluded(self):
        with tempfile.TemporaryDirectory() as tmp:
            ctx = copy.deepcopy(self.ctx); ctx["approved"] = True
            exception = next(e for e in ctx["exceptions"] if e["tipo"] == "CADASTRO_NAO_CONFIRMADO")
            adjustment = {"exception_id": exception["id"], "acao": "ajustar", "valor": "100.00", "justificativa": "Revisão", "actor": "Analista"}
            with self.assertRaises(ValueError): export_artifacts(ctx, [adjustment], tmp)
            adjustment["acao"] = "excluir"
            result = export_artifacts(ctx, [adjustment], tmp)
            self.assertEqual(result["rows"], len(ctx["datasets"]["lancamentos"]))

    def test_zero_adjustment_with_valid_account_removes_both_sides(self):
        with tempfile.TemporaryDirectory() as tmp:
            ctx = copy.deepcopy(self.ctx); ctx["approved"] = True
            exception = next(e for e in ctx["exceptions"] if e["tipo"] == "CREDITO_NAO_IDENTIFICADO")
            before = copy.deepcopy(ctx["datasets"]["lancamentos"])
            target = [r for r in before if exception["id"] in r["__exception_ids"]]
            self.assertEqual(len(target), 2)
            adjustment = {"exception_id": exception["id"], "acao": "ajustar", "valor": "0.00",
                          "conta": "1.1.09.002", "justificativa": "Anular partida revisada", "actor": "Analista"}
            result = export_artifacts(ctx, [adjustment], tmp)
            self.assertEqual(result["rows"], len(before) - 2)
            self.assertEqual(result["debit_total"], result["credit_total"])
            self.assertNotIn(target[0]["entry_id"], (Path(tmp) / "lancamentos_fenix.csv").read_text())
            self.assertEqual(ctx["datasets"]["lancamentos"], before)
            with self.assertRaises(ValueError):
                export_artifacts(ctx, [{**adjustment, "conta": "1"}], tmp)

    def test_synthetic_account_and_non_finite_adjustment_are_rejected(self):
        with tempfile.TemporaryDirectory() as tmp:
            ctx = copy.deepcopy(self.ctx); ctx["approved"] = True
            exception = next(e for e in ctx["exceptions"] if e["tipo"] == "CREDITO_NAO_IDENTIFICADO")
            base = {"exception_id": exception["id"], "acao": "ajustar", "justificativa": "Revisão"}
            with self.assertRaises(ValueError): export_artifacts(ctx, [{**base, "conta": "1"}], tmp)
            with self.assertRaises(ValueError): export_artifacts(ctx, [{**base, "valor": "NaN"}], tmp)

"""Decimal-only summaries of the current source conference (not workflow approvals)."""
from decimal import Decimal


def build_insights(period, results):
    def number(value):
        return Decimal(str(value))
    def money(value):
        return format(value, '.2f')
    def counter():
        return {'count': 0, 'total': Decimal(0)}
    states = {key: counter() for key in ('bloqueante', 'alerta', 'resolvido')}
    types = {}
    for issue in results.get('pendencias', []):
        value = abs(number(issue['valor_brl']))
        decided = issue.get('status') == 'resolved'
        blocking = issue.get('severity') == 'bloqueante'
        bucket = states['resolvido' if decided else 'bloqueante' if blocking else 'alerta']
        bucket['count'] += 1
        bucket['total'] += value
        item = types.setdefault(issue['tipo'], {**counter(), 'open': 0, 'blocking': False})
        item['count'] += 1
        item['blocking'] |= blocking
        if not decided:
            item['open'] += 1
            item['total'] += value
    divergences = {}
    for row in results.get('divergencias', []):
        item = divergences.setdefault(row.get('cnpj', ''), {'count': 0, 'signed': Decimal(0), 'abs': Decimal(0), 'name': row.get('lojista', row.get('cnpj', ''))})
        value = number(row['diferenca_brl'])
        item['count'] += 1
        item['signed'] += value
        item['abs'] += abs(value)
    banks, accounts = {}, {}
    for row in results.get('lancamentos', []):
        value = number(row['valor'])
        inflow, outflow = max(value, Decimal(0)), max(-value, Decimal(0))
        bank = banks.setdefault(row['banco'], {'account': row.get('conta_bancaria', ''), 'count': 0, 'in': Decimal(0), 'out': Decimal(0), 'daily': {}})
        bank['count'] += 1
        bank['in'] += inflow
        bank['out'] += outflow
        day = bank['daily'].setdefault(row['data'], {'in': Decimal(0), 'out': Decimal(0)})
        day['in'] += inflow
        day['out'] += outflow
        account = accounts.setdefault(row.get('conta_codigo', ''), {'name': row.get('conta_descricao', ''), 'count': 0, 'in': Decimal(0), 'out': Decimal(0), 'abs': Decimal(0)})
        account['count'] += 1
        account['in'] += inflow
        account['out'] += outflow
        account['abs'] += abs(value)
    note_lines = {}
    notes = results.get('notas', [])
    for row in notes:
        item = note_lines.setdefault(row['linha_negocio'], counter())
        item['count'] += 1
        item['total'] += number(row['valor_brl'])
    labels = {'bloqueante': 'Bloqueantes abertas', 'alerta': 'Alertas abertos', 'resolvido': 'Decididas'}
    return {
        'comp': period, 'source': 'current_conference',
        'pendencias': {
            'open_brl': money(states['bloqueante']['total'] + states['alerta']['total']),
            'resolved_brl': money(states['resolvido']['total']),
            'open_count': states['bloqueante']['count'] + states['alerta']['count'], 'resolved_count': states['resolvido']['count'],
            'by_state': [{'key': key, 'label': labels[key], 'count': item['count'], 'brl': money(item['total'])} for key, item in states.items()],
            'by_type': [{'key': key, 'label': key.replace('_', ' ').capitalize(), 'count': item['count'], 'open_count': item['open'], 'brl': money(item['total']), 'severity': 'bloqueante' if item['blocking'] else 'alerta'} for key, item in sorted(types.items(), key=lambda pair: (-pair[1]['total'], -pair[1]['open']))],
        },
        'divergencias_por_lojista': [{'cnpj': key, 'lojista': item['name'], 'count': item['count'], 'signed_brl': money(item['signed']), 'abs_brl': money(item['abs'])} for key, item in sorted(divergences.items(), key=lambda pair: -pair[1]['abs'])],
        'bancos': [{'bank': key, 'account': item['account'], 'count': item['count'], 'in_brl': money(item['in']), 'out_brl': money(item['out']), 'net_brl': money(item['in'] - item['out']), 'daily': [{'date': day, 'in_brl': money(values['in']), 'out_brl': money(values['out'])} for day, values in sorted(item['daily'].items())]} for key, item in sorted(banks.items())],
        'contas': [{'code': key, 'name': item['name'], 'count': item['count'], 'abs_brl': money(item['abs']), 'in_brl': money(item['in']), 'out_brl': money(item['out'])} for key, item in sorted(accounts.items(), key=lambda pair: -pair[1]['abs'])],
        'notas': {'total_brl': money(sum((item['total'] for item in note_lines.values()), Decimal(0))), 'count': len(notes), 'by_line': [{'line': key, 'count': item['count'], 'brl': money(item['total'])} for key, item in sorted(note_lines.items())]},
    }
"""Read-only conference views over immutable workflow results, never the latest store result."""
import copy
import csv
import html
import io
import json
import zipfile
from decimal import Decimal
from ..store import Store, EXPORTS
from ..pipeline.service import ServiceError

RESOLVED_STATUSES = {'accepted', 'adjusted', 'excluded', 'resolved'}
OUTPUT_DATASETS = {'comissoes': 'comissoes', 'divergencias': 'divergencias',
                   'notas': 'notas', 'pendencias': 'pendencias', 'rastro': 'rastro',
                   # The dataset named lancamentos is the ERP double-entry
                   # ledger. Official bank lines are a different saved output.
                   'lancamentos': 'bancos_classificados', 'details': 'detalhes_calculo'}
OUTPUT_TITLES = {'comissoes': 'Comissões', 'divergencias': 'Divergências',
                 'notas': 'Notas propostas', 'pendencias': 'Pendências e decisões',
                 'lancamentos': 'Lançamentos classificados', 'rastro': 'Rastro',
                 'details': 'Detalhes do cálculo'}


def _historical_result(run, rows):
    """Read pre-upgrade outputs without calling a calculator or writing a run.

    A missing table is different from a saved empty table. Consumers receive an
    explicit per-output limitation and cannot export a missing table as zeros.
    """
    if not any(name in run['datasets'] for name in ('comissoes', 'notas', 'pendencias', 'rastro')):
        raise ServiceError(409, 'RESULT_NOT_READY', 'A execução ainda não produziu a conferência. Acompanhe os passos do pipeline.')
    unavailable = [{'output': key, 'dataset': name,
                    'message': f'{OUTPUT_TITLES[key]} indisponível: esta execução antiga não preservou o dataset {name}. Nenhum valor foi recalculado.'}
                   for key, name in OUTPUT_DATASETS.items() if name not in run['datasets']]
    missing = {item['output'] for item in unavailable}
    result = {key: rows(name) for key, name in OUTPUT_DATASETS.items()}

    def total(key, column, business=None, absolute=False):
        if key in missing:
            return None
        values = (Decimal(r[column]) for r in result[key] if business is None or r.get('linha_negocio') == business)
        return format(sum((abs(v) if absolute else v for v in values), Decimal(0)), '.2f')

    steps = run.get('steps', [])
    checkout = next((s for s in steps if any(o.get('name') == 'checkout_calculado' for o in s.get('outputs', []))), {})
    remittance = next((s for s in steps if any(o.get('name') == 'cambio_calculado' for o in s.get('outputs', []))), {})
    # Old metrics save stage row counts, not the engine's checkout count after
    # rejecting conflicting duplicate IDs. Expose the metric with its own name.
    stage_counts = {'checkout_stage_rows': checkout.get('metrics', {}).get('rows_out'),
                    'remittance_unique_operations': remittance.get('metrics', {}).get('unique_operations')}
    result['summary'] = {
        'period': run['competencia'], 'checkout_brl': total('comissoes', 'comissao_brl', 'CHECKOUT'),
        'remessa_brl': total('comissoes', 'comissao_brl', 'REMESSA'),
        'divergencias_brl': total('divergencias', 'diferenca_brl'),
        'divergencias_abs_brl': total('divergencias', 'diferenca_brl', absolute=True),
        'notas_brl': total('notas', 'valor_brl'), 'checkout_count': None,
        'remessa_count': stage_counts['remittance_unique_operations'],
        'bank_count': None if 'lancamentos' in missing else len(result['lancamentos']),
        'pendencias_count': None if 'pendencias' in missing else len(result['pendencias']),
        'divergencias_count': None if 'divergencias' in missing else len(result['divergencias']),
        'notas_count': None if 'notas' in missing else len(result['notas']),
        'remittance_tolerance_pp': remittance.get('params', {}).get('tolerancia_pp'),
        'historical_stage_counts': stage_counts,
    }
    limitations = [*unavailable, {'output': 'summary.checkout_count', 'dataset': 'resultado_snapshot',
                   'message': 'A contagem original de operações checkout não foi preservada. A métrica de linhas da etapa permanece em historical_stage_counts; não substitui a contagem após tratamento de duplicidades.'}]
    return result, unavailable, limitations


def run_state(flow, store, run_id, comp=None):
    with flow.lock:
        run = flow.get_run(run_id)
        if comp and run['competencia'] != comp:
            raise ServiceError(422, 'RUN_PERIOD_MISMATCH', 'A execução selecionada pertence a outra competência.')
        def rows(name):
            return copy.deepcopy(flow._rows(run['datasets'][name])) if name in run['datasets'] else []
        meta = run['datasets'].get('resultado_snapshot')
        if meta:
            saved = rows('resultado_snapshot')
            if len(saved) != 1:
                raise ServiceError(409, 'RESULT_UNAVAILABLE', 'O snapshot de resultados desta execução está incompleto.')
            result, unavailable, limitations = saved[0], [], []
            basis = 'resultado_snapshot'
        else:
            result, unavailable, limitations = _historical_result(run, rows)
            basis = 'preserved_datasets'
        exceptions = flow._exceptions(run_id)
        decisions = {e['id']: e for e in exceptions}
        for issue in result['pendencias']:
            decision = decisions.get(issue['id_saida'], {})
            issue['status'] = 'resolved' if decision.get('status') in RESOLVED_STATUSES else 'open'
            issue['review_status'] = decision.get('status', 'open')
            detail = copy.deepcopy(decision.get('decision'))
            if detail:
                detail['note'] = detail.get('note', detail.get('justificativa', ''))
                detail.setdefault('actor', '')
                detail.setdefault('at', '')
                if detail.get('recommendation_id'):
                    issue['operational_status'] = detail.get('follow_up_status', 'pending')
                    issue['follow_up'] = detail.get('follow_up', '')
            issue['decision'] = detail
        summary = result['summary']
        summary.update(open_issues=sum(e.get('status') not in RESOLVED_STATUSES for e in exceptions),
                       resolved_issues=sum(e.get('status') in RESOLVED_STATUSES for e in exceptions),
                       blocking_issues=sum(e.get('status') not in RESOLVED_STATUSES and e.get('severidade') == 'bloqueante' for e in exceptions))
        sums = {}
        for row in result['rastro']:
            sums[row['id_saida']] = sums.get(row['id_saida'], Decimal(0)) + Decimal(row['valor'])
        missing = {item['output'] for item in unavailable}
        errors = [] if 'rastro' in missing else [f"Rastro não fecha: {r['id_saida']}" for key, value in [('comissoes','comissao_brl'),('notas','valor_brl'),('divergencias','diferenca_brl'),('pendencias','valor_brl'),('lancamentos','valor')]
                  for r in result[key] if sums.get(r['id_saida']) != Decimal(r[value])]
        references = run['snapshot'].get('references', {})
        manifest = rows('input_manifest') or copy.deepcopy(run['snapshot'].get('sources', []))
        assumptions = copy.deepcopy(run['snapshot'].get('assumptions', []))
        if 'assumptions' not in run['snapshot']:
            limitations.append({'output': 'assumptions', 'dataset': 'snapshot',
                                'message': 'Esta execução antiga não preservou hipóteses. O catálogo atual não foi usado para reconstruir decisões históricas.'})
        base = store.state()
        return {**base, 'period': run['competencia'], 'competencia': run['competencia'], 'run_id': run_id,
                'assumptions': assumptions, 'assumptions_snapshot_status': 'captured' if 'assumptions' in run['snapshot'] else 'legacy_unavailable',
                'scope': {'competencia': run['competencia'], 'run_id': run_id}, 'read_only': True, 'has_data': True,
                'closing': {'status': run['status'], 'actor': run['created_by'], 'closed_at': run['finished_at'], 'waiver': False, 'reason': ''},
                'results': result, 'summary': summary, 'exceptions': exceptions, 'merchants': references.get('merchants', rows('raw_merchants')),
                'rates': references.get('rates', rows('raw_rates')), 'parameters': references.get('parameters', {}),
