def official_csv(state, name):
    if name not in EXPORTS: raise ServiceError(422, 'INVALID_EXPORT', 'Arquivo oficial desconhecido.')
    key, columns = EXPORTS[name]
    limitation = next((item for item in state.get('unavailable_outputs', []) if item['output'] == key), None)
    if limitation:
        raise ServiceError(409, 'HISTORICAL_OUTPUT_UNAVAILABLE', limitation['message'], [limitation])
    # Public six-file schema is fixed. Rich provenance stays in the snapshot/details.
    out = io.StringIO(newline='')
    writer = csv.DictWriter(out, columns, delimiter=';', lineterminator='\n', extrasaction='ignore')
    writer.writeheader()
    for row in state['results'][key]: writer.writerow(row)
    return out.getvalue().encode('utf-8')

    """Parquet schema metadata → display columns with meaning for tooltips and prompts. Parquet stores
    columns alphabetically; the reading order (identity, date, merchant, type, amounts) comes from `ordem_colunas`."""
    sem = load()
    hidden, rank = set(sem["ocultas"]), {name: i for i, name in enumerate(sem["ordem_colunas"])}
    ordered = sorted(enumerate(schema), key=lambda item: (rank.get(item[1]["name"], len(rank)), item[0]))
